"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useParams } from "react-router-dom";
import { CheckCircle, AlertCircle, Loader2, ArrowLeft, Upload } from "lucide-react";
import Layout from "../../Layout";

export default function EditProduct() {
  const navigate = useNavigate();
  const { id } = useParams();
  const [formData, setFormData] = useState({
    nameProduct: "",
    priceForOne: "",
    quantity: "",
    amount: "",
    unity: "unit",
    safetyThreshold: "",
    zoneId: "",
    nameSupplier: [],
    expirationDate: "",
    bons: [],
    newBon: null,
    newBonDateBon: "",
    newBonType: "Bon de livraison",
    numeroBielle: "",
  });
  const [zones, setZones] = useState([]);
  const [suppliers, setSuppliers] = useState([]);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [previewImage, setPreviewImage] = useState(null);

  useEffect(() => {
    fetchProductAndOptions();
  }, []);

  const fetchProductAndOptions = async () => {
    setIsLoading(true);
    const token = localStorage.getItem("token");

    try {
      const [productRes, zonesRes, suppliersRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/api/products/${id}`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/zones`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/suppliers`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);

      const product = productRes.data;
      setFormData({
        nameProduct: product.nameProduct || "",
        priceForOne: product.priceForOne || "",
        quantity: product.quantity || "",
        amount: product.amount || "",
        unity: product.unity || "unit",
        safetyThreshold: product.safetyThreshold || "",
        zoneId: product.zoneId?._id || product.zoneId || "",
        nameSupplier: product.nameSupplier || [],
        expirationDate: product.expirationDate ? product.expirationDate.split("T")[0] : "",
        bons: product.bons || [],
        newBon: null,
        newBonDateBon: "",
        newBonType: "Bon de livraison",
        numeroBielle: product.numeroBielle || "",
      });

      setPreviewImage(product.bons?.length > 0 ? `${process.env.REACT_APP_API_URL}${product.bons[product.bons.length - 1].image}` : null);
      setZones(zonesRes.data);
      setSuppliers(suppliersRes.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des données");
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "newBon" && files?.length > 0) {
      setFormData({ ...formData, newBon: files[0] });
      const reader = new FileReader();
      reader.onloadend = () => setPreviewImage(reader.result);
      reader.readAsDataURL(files[0]);
    } else if (name === "nameSupplier") {
      setFormData({ ...formData, nameSupplier: [...formData.nameSupplier.slice(0, -1), value] });
    } else {
      const updatedFormData = { ...formData, [name]: value };
      if (name === "priceForOne" || name === "quantity") {
        const price = Number.parseFloat(updatedFormData.priceForOne) || 0;
        const qty = Number.parseInt(updatedFormData.quantity) || 0;
        updatedFormData.amount = (price * qty).toFixed(2);
      }
      setFormData(updatedFormData);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("nameProduct", formData.nameProduct);
      formDataToSend.append("priceForOne", formData.priceForOne);
      formDataToSend.append("quantity", formData.quantity);
      formDataToSend.append("amount", formData.amount);
      formDataToSend.append("unity", formData.unity);
      if (formData.safetyThreshold) formDataToSend.append("safetyThreshold", formData.safetyThreshold);
      formDataToSend.append("zoneId", formData.zoneId);
      formDataToSend.append("nameSupplier", JSON.stringify(formData.nameSupplier));
      formDataToSend.append("expirationDate", formData.expirationDate);
      formDataToSend.append("numeroBielle", formData.numeroBielle);

      if (formData.newBon && formData.newBonDateBon) {
        formDataToSend.append("bon", formData.newBon);
        formDataToSend.append("DateBon", formData.newBonDateBon);
        formDataToSend.append("type", formData.newBonType);
        const lastSupplier = formData.nameSupplier[formData.nameSupplier.length - 1];
        if (lastSupplier) {
          formDataToSend.append("bonSupplier", lastSupplier);
        }
        formDataToSend.append("replaceBons", "true");
      }

      const response = await axios.put(`${process.env.REACT_APP_API_URL}/api/products/${id}`, formDataToSend, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data",
        },
      });

      setFormData((prev) => ({
        ...prev,
        bons: response.data.bons || [],
        newBon: null,
        newBonDateBon: "",
        newBonType: "Bon de livraison",
      }));
      setPreviewImage(null);
      setSuccess("Produit mis à jour avec succès !");

      setTimeout(() => navigate("/ManageProducts"), 2000);
    } catch (err) {
      setError(err.response?.data?.message || err.message || "Erreur lors de la mise à jour du produit");
      console.error("Erreur Frontend :", err.response?.data || err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 py-8">
        <div className="mb-6">
          <button onClick={() => navigate("/ManageProducts")} className="flex items-center text-[#00717F] hover:text-[#C8A45D]">
            <ArrowLeft className="h-4 w-4 mr-1" /> Retour à la liste
          </button>
        </div>

        <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <h2 className="text-2xl font-bold tracking-tight">Modifier un Produit</h2>
            <p className="text-white/80 mt-1 text-sm">Mettez à jour les informations du produit</p>
          </div>

          {(error || success) && (
            <div className={`m-6 p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${error ? "border-red-500" : "border-green-500"} rounded-r-lg flex items-center gap-3`}>
              {error ? <AlertCircle className="h-5 w-5 text-red-500" /> : <CheckCircle className="h-5 w-5 text-green-500" />}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>{error || success}</p>
            </div>
          )}

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                <p className="text-[#00717F] text-sm font-medium">Chargement des données...</p>
              </div>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="p-6">
              <div className="space-y-8">
                <div className="bg-[#F5F6FA]/50 p-6 rounded-xl border border-[#C8A45D/30]/50">
                  <h3 className="text-lg font-medium text-[#00717F] mb-4">Informations du produit</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Nom du Produit</label>
                      <input type="text" name="nameProduct" value={formData.nameProduct} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Prix Unitaire</label>
                      <div className="relative">
                        <input type="number" name="priceForOne" value={formData.priceForOne} onChange={handleChange} className="w-full pl-4 pr-8 py-2.5 border border-gray-300 rounded-lg" min="0" step="0.01" required />
                        <span className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500">DH</span>
                      </div>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Quantité</label>
                      <input type="number" name="quantity" value={formData.quantity} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" min="0" required />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Montant (Calculé)</label>
                      <div className="relative">
                        <input type="text" name="amount" value={formData.amount} className="w-full pl-4 pr-8 py-2.5 border border-gray-300 rounded-lg bg-gray-50 text-gray-500" readOnly />
                        <span className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500">DH</span>
                      </div>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Unité</label>
                      <select name="unity" value={formData.unity} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg">
                        <option value="kg">kg</option>
                        <option value="g">g</option>
                        <option value="unit">unité</option>
                        <option value="liter">litre</option>
                        <option value="ml">ml</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Seuil de Sécurité</label>
                      <input type="number" name="safetyThreshold" value={formData.safetyThreshold} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" min="0" />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Zone</label>
                      <select name="zoneId" value={formData.zoneId} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required>
                        <option value="">Sélectionner une zone</option>
                        {zones.map((zone) => (
                          <option key={zone._id} value={zone._id}>{zone.zoneName}</option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Fournisseur (Dernier)</label>
                      <select
                        name="nameSupplier"
                        value={formData.nameSupplier[formData.nameSupplier.length - 1] || ""}
                        onChange={handleChange}
                        className="w-full px-4 py-2.5 border border-gray-300 rounded-lg"
                        required
                      >
                        <option value="">Sélectionner un fournisseur</option>
                        {suppliers.map((supplier) => (
                          <option key={supplier._id} value={`${supplier.firstName} ${supplier.lastName}`}>
                            {supplier.firstName} {supplier.lastName}
                          </option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Date d'Expiration</label>
                      <input type="date" name="expirationDate" value={formData.expirationDate} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Numéro de Bielle</label>
                      <input type="text" name="numeroBielle" value={formData.numeroBielle} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" />
                    </div>
                  </div>
                </div>

                <div className="bg-[#F5F6FA]/50 p-6 rounded-xl border border-[#C8A45D/30]/50">
                  <h3 className="text-lg font-medium text-[#00717F] mb-4">Nouveau Bon</h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Date du Bon</label>
                      <input type="date" name="newBonDateBon" value={formData.newBonDateBon} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Type de Bon</label>
                      <select name="newBonType" value={formData.newBonType} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg">
                        <option value="Bon de livraison">Bon de livraison</option>
                        <option value="Bon de sortie">Bon de sortie</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Image du Bon</label>
                      <div className="flex items-center justify-center w-full">
                        <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer bg-gray-50 hover:bg-gray-100">
                          <div className="flex flex-col items-center justify-center pt-5 pb-6">
                            {previewImage ? (
                              <img src={previewImage} alt="Aperçu" className="h-20 object-contain mb-2" />
                            ) : (
                              <>
                                <Upload className="w-8 h-8 mb-2 text-gray-500" />
                                <p className="text-sm text-gray-500">Cliquez ou glissez une image ici</p>
                              </>
                            )}
                          </div>
                          <input type="file" name="newBon" accept="image/*" onChange={handleChange} className="hidden" />
                        </label>
                      </div>
                    </div>
                  </div>
                  {formData.bons.length > 0 && (
                    <div className="mt-4">
                      <p className="text-sm font-medium text-gray-700">Bon actuel :</p>
                      <div className="flex gap-2 flex-wrap">
                        {formData.bons.map((bon, i) => (
                          <div key={i} className="flex flex-col items-center">
                            <img src={`${process.env.REACT_APP_API_URL}${bon.image}`} alt={`Bon ${i}`} className="h-10 object-contain" />
                            <span className="text-xs text-gray-500">
                              {bon.type} - {new Date(bon.DateBon).toLocaleDateString('fr-FR')} {bon.supplier ? `- ${bon.supplier}` : ""}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
              <div className="mt-8 flex justify-end gap-4">
                <button type="button" onClick={() => navigate("/ManageProducts")} className="px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium">
                  Annuler
                </button>
                <button type="submit" disabled={isSubmitting} className="px-5 py-2.5 bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-lg hover:opacity-90 font-medium flex items-center gap-2">
                  {isSubmitting ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin" /> Traitement...
                    </>
                  ) : (
                    "Mettre à jour le Produit"
                  )}
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    </Layout>
  );
}
